<?php $section = 'users'; require __DIR__ . '/../../partials/admin-nav.php'; ?>
<div class="page-heading"><div><span class="section-overline">QUẢN LÝ THÀNH VIÊN</span><h1>Tài khoản<span class="accent-period">.</span></h1><p><?= count($users) ?> tài khoản trong hệ thống.</p></div><a href="<?= h(url('/admin/users/create')) ?>" class="btn btn-primary">+ Thêm tài khoản</a></div>
<div class="panel table-scroll"><table><thead><tr><th>Họ tên</th><th>Email</th><th>Vai trò</th><th>Ngày tạo</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($users as $account): ?><tr><td><strong><?= h($account['full_name']) ?></strong></td><td><?= h($account['email']) ?></td><td><span class="status <?= $account['role'] === 'admin' ? 'status-processing' : 'status-pending' ?>"><?= $account['role'] === 'admin' ? 'Quản trị' : 'Khách hàng' ?></span></td><td><?= h(date('d/m/Y', strtotime($account['created_at']))) ?></td><td><div class="action-group"><a class="btn btn-outline btn-sm" href="<?= h(url('/admin/users/' . (int) $account['id'] . '/edit')) ?>">Sửa</a><?php if ((int) $account['id'] !== (int) \App\Core\Auth::user()['id']): ?><form method="post" action="<?= h(url('/admin/users/' . (int) $account['id'] . '/delete')) ?>" onsubmit="return confirm('Xóa tài khoản này?')"><input type="hidden" name="_csrf" value="<?= h(\App\Core\Csrf::token()) ?>"><button type="submit" class="btn btn-danger btn-sm">Xóa</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div>
